from t277_labels import *
import ast,shutil
HERE=Path(__file__).resolve().parent
OUT=ROOT/'stage/runs/t277_physical_hindsight'


def main():
    assert not OUT.exists() and not (HERE/'protocol.json').exists()
    parent=ROOT/'stage/runs/t271_frozen_feature_exploration/protocol.json';base=json.loads(parent.read_text())
    rowpath=ROOT/'stage/runs/t271_frozen_feature_exploration/exploration.jsonl'
    raw=list(map(json.loads,rowpath.read_text().splitlines()))
    chosen=[r for r in raw if r['mode']=='feature_copula' and r['source_reset_id'] in ['dev6_LEFT_13','dev6_RIGHT_13']]
    assert len(chosen)==8 and sum(r['physics_steps'] for r in chosen)==201980
    keys=['id','path','sha256','physics_steps','complete','success','collision','timeout','job','array_hashes','integration_sha256']
    refs=[{k:r[k] for k in keys} for r in chosen]
    # Authenticated full source NPZ includes the nonphysical sampler arrays;
    # eight native-dependent arrays are recomputed from commands in this run.
    for r in refs:r['array_hashes']={k:v for k,v in r['array_hashes'].items() if k in ['states','actions','native_counts','next_states','poses','next_poses','end_flags','rewards']}
    inputs=dict(base['input_hashes']);paths=[parent,rowpath,ROOT/'stage/runs/t271_frozen_feature_exploration/summary.json',
        ROOT/'stage/docs/long_distance_20261101/T271_AUDIT.json',ROOT/'stage/docs/long_distance_20261101/release_receipt_T271.json',
        ROOT/'stage/docs/long_distance_20261101/T276_AUDIT.json',ROOT/'stage/docs/long_distance_20261101/release_receipt_T276.json',
        ROOT/'stage/experiments/t255_overnight/mem_runtime.py',*map(Path,[r['path'] for r in refs]),*HERE.glob('*.py')]
    inputs.update({str(f):sha(f) for f in paths})
    for r in refs:assert sha(r['path'])==r['sha256']
    p=dict(experiment='T277',scope='Only reconstruct8 historical6m center command trajectories and exact physical first-hit witnesses',
        references=refs,input_hashes=inputs,max_commands=8,max_physics=224000,wall_seconds=300,
        per_payload_overhead_bytes=2048,metadata_bytes=640*1024,max_label_bytes=1024,final_bytes=4*1024**2,
        expected_exact_physics_steps=201980,
        global_bytes=1024**3,min_free_bytes=40*1024**3,
        contract='Exactly T271 feature_copula LEFT13 and RIGHT13 four original draws each.8 native commands/224k allphysics max, expected201980, no added seeds/noise/control/scene grid. Actual old float32 commands replayed unchanged, original6m goal/.2radius/56s cap/.002physics/100hold unchanged. Recompute native-dependent120states,nextstates,actions,poses,nextposes,counts,flags,rewards and finalintegration exact; nonphysical sampler arrays are authenticated original references, not falsely called regenerated by command replay. Save only per-native-step float64XY and packed uint8eventflags; sourcefull120 files referenced, not copied.8 fixed future endpoint indices per source linspace(n//4,n-1,8), no replacement for CONTACT/alreadyinside initial radius. First-hit computed full physicalXY with collision priority, record interiorhold and true shortterminal duration, no laterendpoint-as-terminal/bootstrap on unknown suffix. Original task outcomes never relabeled, not8 independent newepisodes/new6m successes or BC/onpolicy-ready replay/Actor120 goalhistory reconstruction.0 optimizer/Actor, no planner/waypoint/runtime teacher/router/Phase. Fullcapacity reserved, unique launch after source sync, no restart/enlargement, raw failures/models retained.')
    for f in HERE.glob('*.py'):ast.parse(f.read_text())
    assert 201980*17+8*2048+p['metadata_bytes']<=p['final_bytes']
    assert used(ROOT/'stage/runs')+p['final_bytes']<p['global_bytes'] and shutil.disk_usage(ROOT).free>=p['min_free_bytes']
    OUT.mkdir();save(HERE/'protocol.json',p);save(OUT/'protocol.json',p)
    print(json.dumps(dict(state='REGISTERED',expected_physics=201980,max_physics=224000,reserve_bytes=p['final_bytes'],worst_payload_metadata=201980*17+8*2048+p['metadata_bytes'])),flush=True)


if __name__=='__main__':main()
